// W41 SMC broker lead notice (routed, not booked), 24 Oct 2026: a consented client routed to an adviser with no booking after
// the grace -> ONE WhatsApp (broker_lead_routed) + ONE email to the adviser, claimed once per lead. Run: node --test automation/tests/W41.test.mjs
// Logic: automation/lib/w41.mjs. Structure: automation/W41.json (generated by automation/build-w41.mjs).
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { createRequire } from 'node:module';
import { runCode, lvViolations, PG_CRED, templateCounts } from './_n8ncode.mjs';
import { checkSql, workflowSql } from './_sqlcheck.mjs';
import { paramCounts } from '../lib/wa.mjs';
import * as L from '../lib/w41.mjs';

const WF = JSON.parse(readFileSync(new URL('../W41.json', import.meta.url), 'utf8'));
const { findUngated } = createRequire(import.meta.url)('../lib/egress-gate.cjs');
const START = 'Start tick (w41.start: gate + parameters)';
const READ = 'Read routed, unbooked SMC leads (past the grace)';
const PLAN = 'Plan notices (w41.plan)';
const CLAIM = 'Claim: one timeline row per lead (RETURNING)';
const CLAIMED = 'Claimed this tick (w41.claimed) -> send items';
const IS_WA = 'WhatsApp item?';
const WA = '-> WhatsApp Send (broker_lead_routed)';
const EMAIL = 'Email adviser from SortMyCover (smc-email-send)';
const SWEEP = 'Route at consent? (w41.sweepStart)';
const SWEEP_READ = 'Read consented, unrouted CTWA leads (WhatsApp window open)';
const SWEEP_PLAN = 'W01 inputs (w41.routeInputs)';
const SWEEP_ROUTE = '-> W01 Lead core (name the adviser, then route; one lead per call)';
const ON = { SMC_BROKER_LEAD_NOTICE_ENABLED: 'true' };
const LEAD = '5730e361-1635-413f-b258-e3157a305a92';
const BROKER = '306062a1-c271-4ae1-8b1e-bb9aed10a5f6';
const row = (over = {}) => ({
  lead_id: LEAD, brand_id: L.SMC_BRAND_ID, broker_id: BROKER, routed_at: '2026-10-24T06:13:37.915Z', created_at: '2026-10-24T06:12:51.176Z',
  consent_at: '2026-10-24T06:12:49.000Z', origin: 'ctwa', is_synthetic: false, first_name: 'Cassiem', last_initial: 'G',
  adviser_first: 'Mark', broker_whatsapp: '+27 82 000 0000', broker_email: 'mark@example.test', opened_page: true, nudges: 1,
  ad_headline: 'Book a 30-minute call with Mark', ...over,
});
const node = (name) => WF.nodes.find((n) => n.name === name);
const out = (name, i = 0) => ((WF.connections[name] && WF.connections[name].main[i]) || []).map((t) => t.node);

test('the generated file is current; id, error workflow, lv-automation form, inactive, every hour, Postgres by name', () => {
  const before = readFileSync(new URL('../W41.json', import.meta.url), 'utf8');
  execFileSync(process.execPath, [new URL('../build-w41.mjs', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1')], { stdio: 'pipe' });
  assert.equal(readFileSync(new URL('../W41.json', import.meta.url), 'utf8'), before, 'W41.json is generated by build-w41.mjs');
  assert.deepEqual(lvViolations(WF, 'smc-w41'), []);
  assert.equal(WF.name, 'W41 SMC broker lead notice (routed, not booked)');
  assert.equal(WF.active, false);
  const trig = WF.nodes.filter((n) => n.type === 'n8n-nodes-base.scheduleTrigger');
  assert.deepEqual(trig.map((n) => n.parameters.rule.interval), [[{ field: 'hours', hoursInterval: 1 }]], 'Jonathan, 24 Oct: it can check every hour');
  const pg = WF.nodes.filter((n) => n.credentials);
  assert.deepEqual(pg.map((n) => [n.name, n.credentials.postgres]), [[READ, { id: '', name: PG_CRED }], [CLAIM, { id: '', name: PG_CRED }], [SWEEP_READ, { id: '', name: PG_CRED }]]);
});

test('wiring: trigger -> start -> read -> plan -> claim -> claimed -> WhatsApp or email; every outside send is gated', () => {
  assert.deepEqual(out('Every hour'), [START, SWEEP]);
  assert.deepEqual(out(START), [READ]);
  assert.deepEqual(out(READ), [PLAN]);
  assert.deepEqual(out(PLAN), [CLAIM]);
  assert.deepEqual(out(CLAIM), [CLAIMED]);
  assert.deepEqual(out(CLAIMED), [IS_WA]);
  assert.deepEqual(out(IS_WA, 0), [WA]);
  assert.deepEqual(out(IS_WA, 1), [`Live send? (${EMAIL})`]);
  assert.deepEqual(findUngated(WF), [], 'DRY_RUN_SENDS gate on every sender (the WhatsApp sub gates itself)');
  assert.equal(node(WA).parameters.workflowId.value, 'smc-whatsapp-send');
  assert.equal(node(WA).parameters.options.waitForSubWorkflow, false);
});

test('the query: every column exists in the migrations; the client\'s number, email and message text never leave the database', () => {
  assert.deepEqual(checkSql(workflowSql(WF)), []);
  const q = node(READ).parameters.query;
  assert.match(q, /l\.routed_at <= now\(\) - make_interval\(mins => \$2::int\)/, 'the grace');
  assert.match(q, /coalesce\(l\.is_synthetic, false\) = false/, 'never test data');
  assert.match(q, /l\.opted_out_at IS NULL/);
  assert.match(q, /a\.status IN \('booked', 'confirmed', 'rescheduled', 'attended', 'no_show'\)/, 'no live booking');
  assert.match(q, /'w41:broker_routed:' \|\| l\.id::text/, 'no second notice');
  assert.match(q, /payload->'provenance'->'referral'->>'headline'/, 'the ad\'s own headline from the consent row');
  assert.doesNotMatch(q, /\bl\.phone\b|\bl\.email\b|\bl\.call_number\b|id_number|\bnotes\b/, 'the lead\'s own number, email, ID number or notes are never selected');
  const claim = node(CLAIM).parameters.query;
  assert.match(claim, /ON CONFLICT \(idempotency_key\) DO NOTHING\s+RETURNING lead_id/);
  assert.match(claim, new RegExp(`'${L.ACTIVITY}'`));
});

test('gates and parameters: off by default, grace 10 minutes (0..1440 from the env)', () => {
  assert.deepEqual(L.start({}), { run: false, reason: 'disabled' });
  assert.deepEqual(L.start(ON), { run: true, brand_id: L.SMC_BRAND_ID, grace_min: 10, limit: L.ROW_LIMIT });
  assert.equal(L.graceMinutes({ SMC_BROKER_LEAD_NOTICE_GRACE_MIN: '30' }), 30);
  assert.equal(L.graceMinutes({ SMC_BROKER_LEAD_NOTICE_GRACE_MIN: '-5' }), 10);
  assert.equal(L.graceMinutes({ SMC_BROKER_LEAD_NOTICE_GRACE_MIN: 'soon' }), 10);
});

test('the message: template broker_lead_routed, first name + initial, when and from where, how far, portal button; counts match the submitted template', () => {
  const p = L.planOne(row());
  assert.ok(p);
  assert.equal(p.key, `w41:broker_routed:${LEAD}`);
  assert.deepEqual(p.payload, { template: 'broker_lead_routed', channels: ['whatsapp', 'email'], routed_at: '2026-10-24T06:13:37.915Z', origin: 'ctwa', ad_headline: 'Book a 30-minute call with Mark', opened_page: true, nudges: 1 });
  assert.equal(p.wa.kind, 'prebuilt');
  assert.equal(p.wa.caller, 'W41');
  assert.equal(p.wa.record, true);
  assert.equal(p.wa.wa.to, '27820000000', 'digits only, the adviser\'s number');
  assert.equal(p.wa.wa.template.name, 'broker_lead_routed');
  const vars = p.wa.wa.template.components[0].parameters.map((x) => x.text);
  assert.deepEqual(vars, ['Mark', 'Cassiem G.', "on Sat 24 Oct at 08:12 via a SortMyCover ad on WhatsApp ('Book a 30-minute call with Mark')", 'opened your booking page but have not confirmed a time']);
  assert.match(p.relay.body.text, /\('Book a 30-minute call with Mark'\)/, 'the email names the ad too');
  assert.equal(p.wa.wa.template.components[1].parameters[0].text, `l/${LEAD}`);
  const want = templateCounts('broker_lead_routed');
  const got = paramCounts(p.wa.wa);
  assert.equal(got.body, want.body);
  assert.equal(got.url, want.url);
  assert.equal(got.quick_reply, want.quick_reply);
  assert.equal(p.relay.body.to[0], 'mark@example.test');
  assert.equal(p.relay.body.from, 'SortMyCover <hello@sortmycover.co.za>');
  assert.equal(p.relay.body.subject, 'New client for you: Cassiem G. (not booked yet)');
  assert.match(p.relay.body.text, /Waiting to book": https:\/\/leadvelocity\.co\.za\/broker\/leads/);
  assert.equal(p.relay.idempotency_key, `w41:broker_routed:${LEAD}:email`);
});

test('how far and where from read correctly; a surname never appears; a stray number in the row is never echoed', () => {
  assert.equal(L.howFarText({ opened_page: false }), 'have not opened your booking page yet');
  assert.equal(L.cameInText({ created_at: '2026-10-25T13:05:00Z', origin: 'lead_ad' }), 'on Sun 25 Oct at 15:05 via a SortMyCover ad form');
  assert.equal(L.cameInText({ consent_at: '2026-10-25T13:05:00Z', origin: 'page' }), 'on Sun 25 Oct at 15:05 via the SortMyCover website');
  assert.equal(L.cameInText({ consent_at: '2026-10-25T13:05:00Z', origin: 'ctwa', ad_headline: ' Book a "30-minute" call\nwith Mark ' }), "on Sun 25 Oct at 15:05 via a SortMyCover ad on WhatsApp ('Book a '30-minute' call with Mark')", 'headline cleaned: one line, straight quotes');
  assert.equal(L.adHeadline({ ad_headline: null }), '');
  assert.equal(L.personLabel({ first_name: 'Lerato', last_initial: 'm' }), 'Lerato M.');
  assert.equal(L.personLabel({ first_name: 'Lerato' }), 'Lerato');
  assert.equal(L.personLabel({ first_name: 'lerato@example.test' }), 'name not given yet');
  const p = L.planOne(row({ last_initial: 'Gusha', phone: '+27 71 555 0495', email: 'c@example.test' }));
  const s = JSON.stringify(p);
  assert.doesNotMatch(s, /Gusha|0495|c@example\.test/, 'only the initial; the client\'s number and email are not in the message even if a wider row arrives');
});

test('who is skipped: test data, no way to reach the adviser; email only when there is no WhatsApp number', () => {
  assert.equal(L.planOne(row({ is_synthetic: true })), null);
  assert.equal(L.planOne(row({ broker_whatsapp: null, broker_email: null })), null);
  const e = L.planOne(row({ broker_whatsapp: '' }));
  assert.equal(e.wa, null);
  assert.deepEqual(e.payload.channels, ['email']);
  const w = L.planOne(row({ broker_email: null }));
  assert.equal(w.relay, null);
  assert.deepEqual(w.payload.channels, ['whatsapp']);
  assert.deepEqual(L.plan([row({ is_synthetic: true }), row()]).map((p) => p.lead_id), [LEAD]);
});

test('claim and fan-out: only the leads whose row was inserted this tick are sent; one WhatsApp item + one email item each', () => {
  const plans = L.plan([row(), row({ lead_id: '11111111-1111-4111-8111-111111111111' })]);
  assert.deepEqual(L.claimRows(plans).map((r) => [r.lead_id, r.key]), [[LEAD, `w41:broker_routed:${LEAD}`], ['11111111-1111-4111-8111-111111111111', 'w41:broker_routed:11111111-1111-4111-8111-111111111111']]);
  const mine = L.claimed(plans, [{ lead_id: LEAD }]);
  assert.deepEqual(mine.map((p) => p.lead_id), [LEAD], 'the other lead was told about on an earlier tick');
  const items = mine.flatMap((p) => L.fanOut(p));
  assert.deepEqual(items.map((i) => i.kind), ['prebuilt', 'smc_relay']);
  assert.equal(items[0].lead_key, `w41:broker_routed:${LEAD}`);
  assert.equal(items[1].relay.idempotency_key, `w41:broker_routed:${LEAD}:email`);
  assert.deepEqual(L.claimed(plans, []), []);
});

test('Code nodes run as written: start (off -> nothing), plan, claimed -> send items', async () => {
  assert.deepEqual(await runCode(WF, START, { env: {} }), []);
  const [s] = await runCode(WF, START, { env: ON });
  assert.deepEqual(s.json, { brand_id: L.SMC_BRAND_ID, grace_min: 10, limit: L.ROW_LIMIT });
  assert.deepEqual(await runCode(WF, PLAN, { items: [] }), []);
  const [p] = await runCode(WF, PLAN, { items: [row()], env: { PORTAL_BASE: 'https://leadvelocity.co.za' } });
  assert.equal(p.json.plans.length, 1);
  assert.equal(p.json.claim_rows[0].key, `w41:broker_routed:${LEAD}`);
  const sent = await runCode(WF, CLAIMED, { items: [{ lead_id: LEAD }], refs: { [PLAN]: p.json } });
  assert.deepEqual(sent.map((i) => i.json.kind), ['prebuilt', 'smc_relay']);
  const none = await runCode(WF, CLAIMED, { items: [], refs: { [PLAN]: p.json } });
  assert.deepEqual(none, []);
});

// ---------------------------------------------------------------- route at consent (Jonathan, 24 Oct 2026, second real lead)
test('route at consent: the hourly branch hands consented, unrouted CTWA leads to W01 core one at a time; on unless SMC_ROUTE_AT_CONSENT=false', async () => {
  assert.deepEqual(out(SWEEP), [SWEEP_READ]);
  assert.deepEqual(out(SWEEP_READ), [SWEEP_PLAN]);
  assert.deepEqual(out(SWEEP_PLAN), [SWEEP_ROUTE]);
  const r = node(SWEEP_ROUTE).parameters;
  assert.equal(r.workflowId.value, 'smc-w01', 'W01 Lead core: the same routing, pool, capacity and disclosure as W03 / W39');
  assert.equal(r.mode, 'each', 'one lead per call: W01 core\'s disclosure branch reads one lead');
  assert.equal(r.options.waitForSubWorkflow, true);
  const q = node(SWEEP_READ).parameters.query;
  assert.match(q, /l\.origin = 'ctwa'/); assert.match(q, /l\.broker_id IS NULL/);
  assert.match(q, /l\.verified_at > now\(\) - make_interval\(hours => \$2::int\)/, 'inside the WhatsApp window, so the adviser can be named first');
  assert.match(q, /coalesce\(l\.is_synthetic, false\) = false/, 'test data never reaches a real adviser through the sweep');
  assert.match(q, /l\.opted_out_at IS NULL/); assert.match(q, /l\.disqualified_reason IS NULL/);
  assert.match(q, /l\.routing_reason IS NULL OR l\.routing_reason IN \('held_disclosure_pending', 'start_page_pending'\)/, 'other holds (budget, capacity, a failed disclosure) are not retried hourly');
  assert.doesNotMatch(q, /\bl\.phone\b|\bl\.email\b/);
  assert.equal(L.SWEEP_WINDOW_H, 23);
  assert.deepEqual(L.sweepStart({}), { run: true, brand_id: L.SMC_BRAND_ID, window_h: 23, limit: L.ROW_LIMIT }, 'on by default (Jonathan chose it)');
  for (const v of ['false', 'FALSE', ' false ']) assert.deepEqual(L.sweepStart({ SMC_ROUTE_AT_CONSENT: v }), { run: false, reason: 'disabled' });
  assert.equal(L.sweepStart({ SMC_ROUTE_AT_CONSENT: 'true' }).run, true);
  assert.deepEqual(L.routeInputs([{ lead_id: 'a' }, { lead_id: 'a' }, null, {}, { lead_id: 'b' }]),
    [{ kind: 'route_and_first_touch', lead_id: 'a', first_touch: false, source: 'W41:consent_sweep' }, { kind: 'route_and_first_touch', lead_id: 'b', first_touch: false, source: 'W41:consent_sweep' }]);
  assert.deepEqual(await runCode(WF, SWEEP, { env: { SMC_ROUTE_AT_CONSENT: 'false' } }), []);
  const [s] = await runCode(WF, SWEEP, { env: {} });
  assert.deepEqual(s.json, { brand_id: L.SMC_BRAND_ID, window_h: 23, limit: L.ROW_LIMIT });
  const items = await runCode(WF, SWEEP_PLAN, { items: [{ lead_id: '3e280148-ef6d-4775-809a-ccd024ddf586' }] });
  assert.deepEqual(items.map((i) => [i.json.kind, i.json.first_touch]), [['route_and_first_touch', false]]);
  assert.deepEqual(await runCode(WF, START, { env: { SMC_ROUTE_AT_CONSENT: 'true' } }), [], 'the notice keeps its own switch');
});
